package com.splitmate.api;import com.splitmate.api.ApiDtos.*;import com.splitmate.domain.User;import com.splitmate.service.SplitMateService;import jakarta.validation.Valid;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/households/{householdId}")public class ExpenseController{private final SplitMateService s;public ExpenseController(SplitMateService s){this.s=s;}private User me(Authentication a){return s.current(a.getName());}@PostMapping("/expenses")public ExpenseView create(@PathVariable Long householdId,@Valid @RequestBody CreateExpense x,Authentication a){if(!householdId.equals(x.householdId()))throw com.splitmate.service.ApiException.bad("Household id does not match request");return s.createExpense(x,me(a));}@GetMapping("/expenses")public PageView<ExpenseView> list(@PathVariable Long householdId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(required=false)String category,Authentication a){return s.expensePage(householdId,me(a),page,size,category);}@GetMapping("/summary")public Summary summary(@PathVariable Long householdId,Authentication a){return s.summary(householdId,me(a));}@GetMapping("/settlements")public java.util.List<SettlementView> settlements(@PathVariable Long householdId,Authentication a){return s.listSettlements(householdId,me(a));}@PostMapping("/settlements")public SettlementView createSettlement(@PathVariable Long householdId,@Valid @RequestBody CreateSettlement data,Authentication a){return s.createSettlement(householdId,data.payeeId(),data.amount(),me(a));}@PatchMapping("/settlements/{id}/paid")public SettlementView paid(@PathVariable Long householdId,@PathVariable Long id,Authentication a){return s.markPaid(householdId,id,me(a));}}
